% ex5_plot.m
%
% Purpose:
%   Plot the Example 5 Volterra pseudospectrum from the CSV generated by the
%   Julia pseudospectrum script.
%
% Problem:
%   Complex Bessel-kernel Volterra pseudospectrum in a Legendre basis.
%
% Input files:
%   data/ex5_volterra_schur_besselj1_pseudospectrum.csv
%
% Output files:
%   figures/ex5_pseudospectrum.pdf
%   figures/ex5_pseudospectrum.png
%
% Run:
%   matlab -batch "run('examples/ex5_psespectra/ex5_plot.m')"

clear; clc; close all;

scriptDir = fileparts(mfilename('fullpath'));
addpath(fullfile(fileparts(fileparts(scriptDir)), 'tools'));
paperStyle = voltopt_plot_style();
dataDir = fullfile(scriptDir, 'data');
figDir = fullfile(scriptDir, 'figures');

if ~isfolder(figDir)
    mkdir(figDir);
end

csvfile = fullfile(dataDir, 'ex5_volterra_schur_besselj1_pseudospectrum.csv');
if ~isfile(csvfile)
    error('Cannot find CSV file: %s', csvfile);
end

T = readtable(csvfile);

x = unique(T.x, "sorted");
y = unique(T.y, "sorted");

nx = numel(x);
ny = numel(y);

Z = reshape(T.log10_pse, [ny, nx]).';

[X, Y] = meshgrid(x, y);
Zplot = Z.';

levels = -14:1:-1;

fig = figure("Color", "w", "Units", "centimeters", ...
    "Position", [2, 2, paperStyle.FigureSize]);
ax = axes(fig);

contour(ax, X, Y, Zplot, levels, ...
    "LineWidth", paperStyle.PlotLineWidth);

colormap(turbo);

cb = colorbar(ax);
cb.Label.Interpreter = "latex";
cb.Label.String = "$\log_{10}(\epsilon)$";

clim([min(levels), max(levels)]);

xlabel("$\mathrm{Re}(z)$", "Interpreter", "latex");
ylabel("$\mathrm{Im}(z)$", "Interpreter", "latex");
%title("Pseudospectrum", "Interpreter", "latex");

axis(ax, 'equal');
axis(ax, 'tight');
box(ax, 'on');
set(ax, "FontName", paperStyle.FontName, ...
    "FontSize", paperStyle.TickFontSize, ...
    "LineWidth", paperStyle.AxesLineWidth);

outpdf = fullfile(figDir, "ex5_pseudospectrum.pdf");
outpng = fullfile(figDir, "ex5_pseudospectrum.png");

voltopt_export_figure(fig, ax, outpdf, outpng, 'standard');

fprintf('Figure saved to:\n  %s\n  %s\n', outpdf, outpng);
